# The three-knot restricted cubic spline uses rms/Hmisc norm = 2.
age_spline <- function(age, knots) {
  k1 <- knots[1]; k2 <- knots[2]; k3 <- knots[3]
  (pmax(age - k1, 0)^3 - pmax(age - k2, 0)^3 * (k3 - k1) / (k3 - k2) +
     pmax(age - k3, 0)^3 * (k2 - k1) / (k3 - k2)) / (k3 - k1)^2
}

predict_cdai <- function(model_id, values) {
  if (!model_id %in% names(model_parameters$models)) stop("Choose a model.")
  model <- model_parameters$models[[model_id]]
  labels <- c(age_years = "Age", cdai_score_no = "Baseline CDAI", nlr_8 = "NLR", lmr_8 = "LMR",
              plr_8 = "PLR", neutrophile_8 = "Neutrophils", platelet_8 = "Platelets",
              lymphocyte_8 = "Lymphocytes", monocyte_8 = "Monocytes")
  for (v in names(model$limits)) {
    x <- values[[v]]; bounds <- model$limits[[v]]
    if (length(x) != 1L || !is.numeric(x) || !is.finite(x)) {
      stop(paste("Enter a valid value for", labels[v]), call. = FALSE)
    }
    if (x < bounds["min"] - 1e-12 || x > bounds["max"] + 1e-12) {
      stop(sprintf("%s must be within the development range (%g to %g).", labels[v], bounds["min"], bounds["max"]), call. = FALSE)
    }
  }
  if (!values$gender %in% c("Male", "Female")) stop("Choose male or female.")
  if (!values$previous_ibd_related_surge %in% c("No", "Yes")) stop("Choose the prior surgery status.")
  design <- c("gender=Female" = as.integer(values$gender == "Female"),
              age_years = values$age_years, "age_years'" = age_spline(values$age_years, model$age_knots),
              "previous_ibd_related_surge=Yes" = as.integer(values$previous_ibd_related_surge == "Yes"),
              cdai_score_no = values$cdai_score_no)
  if (model_id == "model1") {
    design <- c(design, plr_8 = log(values$plr_8), lmr_8 = log(values$lmr_8), nlr_8 = log(values$nlr_8))
  } else {
    design <- c(design, neutrophile_8 = values$neutrophile_8, platelet_8 = values$platelet_8,
                monocyte_8 = values$monocyte_8, lymphocyte_8 = values$lymphocyte_8)
  }
  eta <- sum(design * model$coefficients[names(design)])
  cumulative <- plogis(model$intercepts + eta)
  probabilities <- c(1 - cumulative[1], head(cumulative, -1) - tail(cumulative, -1), tail(cumulative, 1))
  if (any(!is.finite(probabilities)) || any(probabilities < 0) || abs(sum(probabilities) - 1) > 1e-12) {
    stop("The model could not calculate valid probabilities.")
  }
  unname(probabilities)
}

* { box-sizing: border-box; }
body { background: #f3f6f8; color: #1a3041; font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif; font-size: 15px; line-height: 1.55; }
.container-fluid { padding: 0; }
.page-wrap { max-width: 1220px; margin: 0 auto; padding: 38px 30px 24px; }
.app-header { display: flex; justify-content: space-between; align-items: center; gap: 24px; margin-bottom: 30px; }
.eyebrow { color: #497380; letter-spacing: 1.5px; font-size: 11px; font-weight: 700; margin-bottom: 8px; }
h1 { margin: 0 0 10px; font-size: 34px; font-weight: 650; letter-spacing: -.8px; }
.app-header p { color: #526775; margin: 0; max-width: 690px; }
.version-badge { flex-shrink: 0; background: #e4eef0; border-radius: 9px; padding: 10px 16px; font-size: 18px; font-weight: 700; color: #286371; text-align: center; }
.version-badge span { display: block; font-size: 11px; font-weight: 400; margin-top: 1px; }
.app-layout { display: grid; grid-template-columns: 318px minmax(0, 1fr); gap: 24px; align-items: start; }
.input-panel, .results-card, .context-card { border: 1px solid #dce4e9; border-radius: 12px; background: #fff; padding: 24px; }
h2 { font-size: 20px; font-weight: 650; margin: 0 0 18px; }
h3 { font-size: 13px; font-weight: 700; margin: 24px 0 14px; color: #3c5d6c; }
.input-pair { display: grid; grid-template-columns: minmax(0,1fr) minmax(0,1fr); gap: 14px; }
.form-group, .shiny-input-container:not(.shiny-input-container-inline) { width: 100%; margin-bottom: 15px; }
.control-label { font-size: 12px; font-weight: 600; margin-bottom: 6px; }
.form-control { border: 1px solid #cbd6de; border-radius: 6px; height: 39px; color: #203c4d; box-shadow: none; font-size: 14px; padding: 7px 10px; }
.form-control:focus { border-color: #317c8e; box-shadow: 0 0 0 2px #e7f1f3; }
.field-note { font-size: 12px; color: #667c89; margin: -5px 0 14px; }
.range-note { margin: 16px 0 0; line-height: 1.5; }
.reset-button { background: #fff; color: #355968; border: 1px solid #cbd8df; border-radius: 6px; padding: 8px 14px; font-size: 13px; }
.results-panel { min-width: 0; }
.section-top { display: flex; justify-content: space-between; align-items: start; gap: 12px; margin-bottom: 28px; }
.section-top h2 { margin-bottom: 5px; }
#model_name { color: #69808e; font-size: 12px; }
.live-badge { background: #edf4f5; color: #46727d; padding: 5px 8px; border-radius: 5px; font-size: 10px; white-space: nowrap; }
.probability-row { margin-bottom: 23px; }
.probability-label { display: grid; grid-template-columns: 65px minmax(0,1fr) 58px; gap: 10px; font-size: 13px; align-items: baseline; margin-bottom: 9px; }
.group-number { color: #718590; font-size: 11px; }
.probability-label strong { font-size: 16px; text-align: right; font-variant-numeric: tabular-nums; color: #244e60; }
.bar-track { height: 17px; background: #f0f4f6; border-radius: 4px; overflow: hidden; }
.bar-fill { height: 100%; border-radius: 4px; transition: width .2s ease; }
.result-summary { font-size: 13px; background: #f3f7f8; border-radius: 6px; padding: 12px 14px; margin: 27px 0 18px; color: #355d6d; }
.download-button { border: 1px solid #cbd8df; border-radius: 6px; color: #355968; padding: 8px 13px; background: #fff; font-size: 12px; }
.context-card { margin-top: 20px; color: #58717e; font-size: 13px; }
.context-card h2 { font-size: 16px; color: #294b5c; margin-bottom: 12px; }
.context-card p { margin: 0 0 11px; }
.context-card details { margin-top: 17px; border-top: 1px solid #e5ecef; padding-top: 12px; }
.context-card summary { cursor: pointer; font-weight: 600; color: #356472; }
.context-card details p:first-of-type { margin-top: 13px; }
.app-footer { color: #78909b; font-size: 11px; padding: 20px 0 0; }
.shiny-output-error-validation { color: #985d24; font-size: 14px; padding: 16px 0; }
@media (max-width: 800px) { .page-wrap { padding: 24px 17px; } .app-layout { grid-template-columns: 1fr; gap: 18px; } h1 { font-size: 28px; } .version-badge { padding: 8px 10px; } .app-header { align-items: start; } .live-badge { display: none; } }
@media (max-width: 420px) { .version-badge { display: none; } .input-panel, .results-card, .context-card { padding: 19px; } .probability-label { grid-template-columns: 54px minmax(0,1fr) 52px; gap: 5px; font-size: 12px; } }
